                    '<button class="ssp-btn-danger btn-delete-messenger" data-id="' + m.id + '">\u062D\u0630\u0641</button>' +
                    '</div></div>' +
                    '<span id="messenger_status_' + m.id + '" class="ssp-connection-status"></span></div>';
            }

