                var showOnboarding = <?php echo (empty($messengers) && empty($wp_sites) && $total_count === 0) ? 'true' : 'false'; ?>;
                var dismissed = localStorage.getItem('ssp_onboarding_dismissed');
                if (showOnboarding && !dismissed) {
